import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';

const root = process.argv[2];
const data = path.join(root, 'custom-data');
const library = path.join(root, 'selected-library');
fs.mkdirSync(library);
fs.writeFileSync(path.join(root, '.env'), `DATA_DIR="${data}"\nADMIN_PASSWORD_HASH=fixture\nGHARMONIZE_ACCESS_REVISION=${'a'.repeat(32)}\nRETAG_ONLINE_METADATA=0\n`);
await import('../../modules/loadEnvironment.js');
const { processRetagDirectoryJob } = await import('../../modules/retag.js');
const { parseFile } = await import('music-metadata');
const source = path.join(library, 'old.flac');
execFileSync('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-f', 'lavfi', '-i', 'anullsrc=r=8000:cl=mono', '-t', '0.1', '-metadata', 'artist=Fixture Artist', '-metadata', 'title=Fixture Title', '-c:a', 'flac', source], { timeout: 10_000 });
const tempRoot = path.join(data, 'temp');
const job = { id: 'runtime-retag-fixture', metadata: {}, status: 'queued' };
await processRetagDirectoryJob(job, { directoryPath: library, tempRoot });
assert.equal(job.status, 'completed');
assert.equal(job.metadata.retagStats.tagged, 1);
assert.equal(job.metadata.retagStats.failed, 0);
const result = path.join(library, 'Fixture Artist - Fixture Title.flac');
assert.ok(fs.existsSync(result));
assert.ok(!fs.existsSync(source));
assert.equal((await parseFile(result)).common.title, 'Fixture Title');
assert.ok(!fs.existsSync(path.join(data, 'outputs', path.basename(result))));
assert.ok(!fs.existsSync(path.join(tempRoot, job.id)));
console.log('RETAG_PATHS_OK');
process.exit(0);
